CREATE TABLE `credential_assets` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`name` VARCHAR(160) NOT NULL,`kind` ENUM('api_key','account_secret','cookie_bundle','private_key','browser_profile') NOT NULL,`payload_ciphertext` MEDIUMBLOB NOT NULL,`payload_nonce` BINARY(12) NOT NULL,`payload_auth_tag` BINARY(16) NOT NULL,`key_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`fingerprint` CHAR(16) CHARACTER SET ascii NOT NULL,`status` ENUM('active','revoked') NOT NULL,`expires_at` DATETIME(3) NULL,`rotated_at` DATETIME(3) NULL,`revoked_at` DATETIME(3) NULL,`revoked_by` CHAR(36) CHARACTER SET ascii NULL,`revocation_reason` VARCHAR(500) NULL,`version` INT UNSIGNED NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`updated_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_credential_asset_provider` (`id`,`provider_id`),KEY `idx_credential_asset_provider_status` (`provider_id`,`status`,`updated_at`),CONSTRAINT `fk_credential_asset_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`),CONSTRAINT `fk_credential_asset_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),CONSTRAINT `fk_credential_asset_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),CONSTRAINT `fk_credential_asset_revoked_by` FOREIGN KEY (`revoked_by`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `credential_asset_versions` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`credential_asset_id` CHAR(36) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL,`payload_ciphertext` MEDIUMBLOB NOT NULL,`payload_nonce` BINARY(12) NOT NULL,`payload_auth_tag` BINARY(16) NOT NULL,`key_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`fingerprint` CHAR(16) CHARACTER SET ascii NOT NULL,`action` ENUM('created','rotated','revoked') NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_credential_asset_version` (`credential_asset_id`,`version`),KEY `idx_credential_version_trace` (`trace_id`),CONSTRAINT `fk_credential_version_asset` FOREIGN KEY (`credential_asset_id`) REFERENCES `credential_assets` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_credential_version_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `credential_asset_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route` VARCHAR(200) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`credential_asset_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_version` INT UNSIGNED NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_credential_asset_operation` (`actor_id`,`route`,`idempotency_key`),CONSTRAINT `fk_credential_operation_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),CONSTRAINT `fk_credential_operation_asset` FOREIGN KEY (`credential_asset_id`) REFERENCES `credential_assets` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `crawler_profiles` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`credential_asset_id` CHAR(36) CHARACTER SET ascii NOT NULL,`code` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`name` VARCHAR(160) NOT NULL,`browser_family` ENUM('chromium') NOT NULL,`locale` VARCHAR(40) CHARACTER SET ascii NOT NULL,`timezone` VARCHAR(80) CHARACTER SET ascii NOT NULL,`status` ENUM('active','disabled','revoked') NOT NULL,`version` INT UNSIGNED NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`updated_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_crawler_profile_code` (`code`),KEY `idx_crawler_profile_provider_status` (`provider_id`,`status`),CONSTRAINT `fk_crawler_profile_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`),CONSTRAINT `fk_crawler_profile_asset_provider` FOREIGN KEY (`credential_asset_id`,`provider_id`) REFERENCES `credential_assets` (`id`,`provider_id`),CONSTRAINT `fk_crawler_profile_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),CONSTRAINT `fk_crawler_profile_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `crawler_profile_versions` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`crawler_profile_id` CHAR(36) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL,`snapshot_json` JSON NOT NULL,`action` ENUM('created','updated','revoked') NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_crawler_profile_version` (`crawler_profile_id`,`version`),KEY `idx_crawler_profile_trace` (`trace_id`),CONSTRAINT `fk_crawler_profile_version_profile` FOREIGN KEY (`crawler_profile_id`) REFERENCES `crawler_profiles` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_crawler_profile_version_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `crawler_profile_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route` VARCHAR(200) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`crawler_profile_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_version` INT UNSIGNED NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_crawler_profile_operation` (`actor_id`,`route`,`idempotency_key`),CONSTRAINT `fk_crawler_profile_operation_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),CONSTRAINT `fk_crawler_profile_operation_profile` FOREIGN KEY (`crawler_profile_id`) REFERENCES `crawler_profiles` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
